import {loadSaved,saveSafely} from './storage.mjs';
import {LANGS,MODES,norm,tokens,shuffled,free,freeTiles,makePairs,pairHint,makeSequence,payloadsFor,matchesText,prefixMatch,sentenceOptions,sequenceHint,repairSequence,routeKey,localDay,newProgress,memoryKey,updateMemory,validateProgress,mergeProgress} from './engine.mjs';
import {AudioPlayer} from './audio.mjs';
import {icon} from './icons.mjs';
const {COURSE,UI,MANIFEST,AUDIO={}}=globalThis.PAROLA_DATA;
const NAMES={it:'Italiano',en:'English',ar:'العربية',ru:'Русский'},GLYPHS={it:'IT',en:'EN',ar:'ع',ru:'Я'};
const UNIT=new Map(COURSE.units.map(u=>[u.id,u])),ITEM=new Map([...COURSE.items,...COURSE.vocab].map(i=>[i.id,i]));
const KEY='parola-mahjong-v6';
const root=document.querySelector('#app'),announcer=document.querySelector('#announcer');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>JSON.parse(JSON.stringify(x));
let storageOK=true,store=load(),view='home',selectedUnit='greetings',selectedMode='pair',game=null,lastSummary=null,search='',showAllNotebook=false,feedback='',toastTimer=null;
let helpAnswer='',modalOpen=false;
function sanitizeSession(g) {
 try {
  if(!g||![5,6].includes(g.version)||!UNIT.has(g.unit)||!MODES.includes(g.mode)||!LANGS.includes(g.target)||!LANGS.includes(g.support)||g.target===g.support||g.route!==`${g.support}>${g.target}`)return null;
  if(typeof g.id!=='string'||g.id.length>80||!['playing','roundDone'].includes(g.phase))return null;
  if(!Array.isArray(g.pool)||g.pool.length<1||g.pool.length>12||g.pool.some(id=>!ITEM.has(id)))return null;
  if(!Array.isArray(g.board)||!g.board.length||g.board.length>120)return null;
  const ids=new Set(),positions=new Set();
  for(const tile of g.board){
   if(!Number.isInteger(tile.id)||tile.id<0||ids.has(tile.id)||!g.pool.includes(tile.itemId)||!LANGS.includes(tile.lang)||!Number.isInteger(tile.x)||tile.x<0||tile.x>10||!Number.isInteger(tile.y)||tile.y<0||tile.y>30||![0,1,2,3].includes(tile.z)||typeof tile.gone!=='boolean'||!['target','support','word'].includes(tile.type)||typeof tile.text!=='string'||tile.text.length>200)return null;
   const at=`${tile.x}:${tile.y}:${tile.z}`;if(positions.has(at))return null;ids.add(tile.id);positions.add(at);
  }
  if(!Array.isArray(g.completed)||g.completed.some(id=>!g.pool.includes(id))||new Set(g.completed).size!==g.completed.length)return null;
  if(!Array.isArray(g.results)||g.results.length>12||g.results.some(r=>!r||!g.pool.includes(r.itemId)||!Number.isFinite(r.mistakes)))return null;
  if(!Array.isArray(g.prefix)||g.prefix.length>120||g.prefix.some(x=>!x||!ids.has(x.id)||typeof x.text!=='string'||x.text.length>200))return null;
  if(!g.helpUses||!['hint','shuffle'].every(k=>Number.isInteger(g.helpUses[k])&&g.helpUses[k]>=0&&g.helpUses[k]<=10000))return null;
  if(!['score','combo','bestCombo','errors','tries','round'].every(k=>Number.isFinite(g[k])&&g[k]>=0&&g[k]<=100000))return null;
  if(!g.assist||!g.mistakes||typeof g.assist!=='object'||typeof g.mistakes!=='object')return null;
  const out=clone(g);out.version=6;out.history=[];
  for(const k of ['heard','revealed'])out[k]=Array.isArray(g[k])?[...new Set(g[k].filter(id=>g.pool.includes(id)))]:[];
  out.hints=Array.isArray(g.hints)?g.hints.filter(id=>ids.has(id)):[];
  out.assist={};out.mistakes={};for(const id of g.pool){if(g.assist[id])out.assist[id]=true;if(Number.isFinite(g.mistakes[id]))out.mistakes[id]=Math.min(10000,Math.max(0,Math.floor(g.mistakes[id])));}
  out.pairSelected=ids.has(g.pairSelected)?g.pairSelected:null;
  if(g.helpPending){const h=g.helpPending;if(!['hint','shuffle'].includes(h.kind)||!ITEM.has(h.itemId))return null;out.helpPending={kind:h.kind,itemId:h.itemId,tries:Math.max(0,Math.min(10000,Number(h.tries)||0)),answer:String(h.answer||'').slice(0,500),guided:Boolean(h.guided),error:typeof h.error==='string'?h.error:false};}
  out.writePending=null;
  if(g.writePending){const w=g.writePending;if(!ids.has(w.tileId)||!g.pool.includes(w.itemId))return null;out.writePending={tileId:w.tileId,itemId:w.itemId,tries:Math.max(0,Math.min(10000,Number(w.tries)||0)),answer:String(w.answer||'').slice(0,500),guided:Boolean(w.guided),error:typeof w.error==='string'?w.error:false};}
  if(g.feedback&&(!UI.it[g.feedback.key]||g.feedback.item&&!ITEM.has(g.feedback.item)))out.feedback=null;
  return out;
 }catch{return null;}
}
function validSession(g){return Boolean(sanitizeSession(g));}
function cleanSaved(p){const clean=validateProgress(p);clean.sessions={};for(const [k,g]of Object.entries(p.sessions||{}).slice(0,12)){const session=sanitizeSession(g);if(session&&k===session.route)clean.sessions[k]=session;}return clean;}
function freshSaved(){const p=newProgress();p.sessions={};return p;}
function load(){try{const result=loadSaved(localStorage,KEY,cleanSaved,freshSaved,['parola-mahjong-v5','parola-mahjong-v5.backup']);storageOK=result.ok;return result.value;}catch{storageOK=false;return freshSaved();}}
function save(){if(game&&view==='game')store.sessions[game.route]=game;try{storageOK=saveSafely(localStorage,KEY,store,cleanSaved);}catch{storageOK=false;}}
function t(key,vars={}){let s=UI[store.settings.ui]?.[key];if(s==null){console.error('Missing translation',key);s=`[${key}]`;}return s.replace(/\{(\w+)\}/g,(_,k)=>vars[k]??`{${k}}`);}
function dir(l){return l==='ar'?'rtl':'ltr';}
function route(){return routeKey(store.settings);}
function missionKey(unit,mode,r=route()){return`${r}|${mode}|${unit}`;}
function unitItems(u){return UNIT.get(u).items.map(id=>ITEM.get(id));}
function title(u){return UNIT.get(u).title[store.settings.ui];}
function modeName(mode){return t(mode==='listen'?'listen':mode);}
function modeIcon(mode){return mode==='listen'?'ear':mode;}
function totalXP(){return Math.floor(Object.values(store.missions).reduce((n,m)=>n+m.score,0)/10);}
function completedCount(){return Object.keys(store.missions).filter(k=>k.startsWith(route()+'|')).length;}
function nextUnit(){return COURSE.units.find(u=>MODES.some(m=>!store.missions[missionKey(u.id,m)]))||COURSE.units[0];}
function nextMode(u){return MODES.find(m=>!store.missions[missionKey(u,m)])||'pair';}
function routeHTML(){return `<span class="langcoin">${GLYPHS[store.settings.support]}</span><bdi>${NAMES[store.settings.support]}</bdi>${icon('arrow',16,'right-arrow')}<span class="langcoin target">${GLYPHS[store.settings.target]}</span><bdi>${NAMES[store.settings.target]}</bdi>`;}
function button(action,label,ico='arrow',cls='',attrs=''){return `<button class="button ${cls}" data-action="${action}" ${attrs}>${esc(label)}${icon(ico,19,'right-arrow')}</button>`;}
function sounds(lang,text,context='',slow=true){return `<div class="audio-buttons"><button class="sound" data-action="speak" data-lang="${lang}" data-text="${esc(text)}" data-context="${esc(context)}" title="${esc(t('listen'))}" aria-label="${esc(t('listen')+': '+text)}">${icon('speaker',19)}</button>${slow?`<button class="sound slow" data-action="speak" data-lang="${lang}" data-text="${esc(text)}" data-context="${esc(context)}" data-rate="0.8" title="${esc(t('slow'))}" aria-label="${esc(t('slow')+': '+text)}">${esc(t('slowRate'))}</button>`:''}</div>`;}
const player=new AudioPlayer(MANIFEST,AUDIO,key=>toast(t(key),true));
function toast(msg,warn=false){clearTimeout(toastTimer);document.querySelector('.toast')?.remove();const e=document.createElement('div');e.className='toast'+(warn?' warn':'');e.role='status';e.textContent=msg;document.body.append(e);announcer.textContent=msg;toastTimer=setTimeout(()=>e.remove(),warn?6500:3400);}
function fx(good=true){if(!store.settings.effects)return;try{const Ctx=globalThis.AudioContext||globalThis.webkitAudioContext;if(!Ctx)return;const a=new Ctx();const o=a.createOscillator(),g=a.createGain();o.connect(g);g.connect(a.destination);o.type='sine';o.frequency.setValueAtTime(good?560:230,a.currentTime);o.frequency.exponentialRampToValueAtTime(good?830:180,a.currentTime+.13);g.gain.setValueAtTime(.045,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+.17);o.start();o.stop(a.currentTime+.18);o.onended=()=>a.close();}catch{}}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const e=document.createElement('div');e.className='confetti';e.innerHTML=Array.from({length:27},(_,i)=>`<i style="left:${(i*37)%100}%;animation-delay:${(i%6)*.08}s;transform:rotate(${i*29}deg)"></i>`).join('');document.body.append(e);setTimeout(()=>e.remove(),2700);}
function nav(action){if(view==='game'){save();player.stop();}closeDialog();view=action;game=null;render();window.scrollTo({top:0,behavior:'instant'});}
function render(){
 document.documentElement.lang=store.settings.ui;document.documentElement.dir=dir(store.settings.ui);document.body.classList.toggle('large',store.settings.large);
 const activeNav=['intro','game','summary'].includes(view)?'home':view;
 root.innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brandmark">${icon('tile',24)}</span><span>parola<span class="dot">.</span></span></div><nav class="nav" aria-label="${esc(t('path'))}">${[['home','path'],['play','grid'],['review','review'],['notebook','book'],['settings','settings']].map(([v,i])=>`<button class="navbtn ${activeNav===v?'current':''}" data-action="nav" data-view="${v}" ${activeNav===v?'aria-current="page"':''} title="${esc(t(v))}" aria-label="${esc(t(v))}">${icon(i,23)}<span>${esc(t(v))}</span></button>`).join('')}</nav><div class="sidebase"><div class="mini-mascot"><i class="eye"></i><i class="eye"></i></div><p>${esc(t('noHearts'))}</p></div></aside><main class="main"><header class="topbar"><button class="routebtn" data-action="nav" data-view="settings" aria-label="${esc(t('settings'))}">${routeHTML()}${icon('down',15)}</button><div class="topstats"><span class="topstat flame" title="${esc(t('streakDays'))}">${icon('flame',23)}${store.days.length}</span><span class="topstat xp">${icon('spark',23)}${totalXP()} <small>XP</small></span><button class="profile" data-action="nav" data-view="settings" aria-label="${esc(t('uiLanguage'))}">${GLYPHS[store.settings.ui]}</button></div></header><div id="view">${({home:homeView,play:playView,intro:introView,game:gameView,summary:summaryView,settings:settingsView,review:reviewView,notebook:notebookView}[view]||homeView)()}</div>${!storageOK?`<div class="note-warning">${esc(t('saveError'))}</div>`:''}<footer class="footer"><span>PAROLA / 06 · ${esc(t('brandTag'))}</span><span>${esc(t('buildInfo'))}</span></footer></main></div>`;
 if(view==='game'){sizeBoard();save();if(game?.helpPending)openHelpDialog();else if(game?.writePending)openWriteDialog();}
}
function art(){return `<div class="hero-art" aria-hidden="true"><div class="hero-blob"></div><div class="art-spark">✧</div><div class="tilefriend"><i class="eye"></i><i class="eye"></i><i class="cheek"></i><i class="cheek"></i></div><span class="floatword a">ciao!</span><span class="floatword b">hello!</span><span class="floatword c" lang="ar">مرحبًا</span><span class="floatword d" lang="ru">привет!</span></div>`;}
function unitCard(u){const done=MODES.filter(m=>store.missions[missionKey(u.id,m)]).length;return `<button class="unitcard ${nextUnit().id===u.id?'recommended':''}" data-action="intro" data-unit="${u.id}" aria-label="${esc(t('unit',{n:u.index+1})+': '+title(u.id))}"><span class="unitnum">${done===MODES.length?icon('check',24):String(u.index+1).padStart(2,'0')}</span><span class="unittext"><h3>${esc(title(u.id))}</h3><span class="minimodes">${MODES.map(m=>`<span class="modedot ${store.missions[missionKey(u.id,m)]?'done':''}" title="${esc(modeName(m))}">${icon(store.missions[missionKey(u.id,m)]?'check':modeIcon(m),12)}</span>`).join('')}</span></span>${icon('chevron',21,'unittrail')}</button>`;}
function courseList(){return COURSE.chapters.map((c,j)=>`<section><div class="chapter-header"><span class="chapter-icon">${icon(['spark','globe','book','tile'][j],21)}</span><div><div class="eyebrow">${esc(t('chapter',{n:j+1}))}</div><h3>${esc(c[store.settings.ui])}</h3></div><span class="line"></span></div><div class="units">${COURSE.units.filter(u=>u.chapter===j).map(unitCard).join('')}</div></section>`).join('');}
function homeView(){const u=nextUnit(),resume=store.sessions[route()],due=dueEntries();return `<section class="hero"><div><div class="eyebrow">${esc(t('coreTag'))}</div><h1>${esc(t('hero1'))}<br><em>${esc(t('hero2'))}</em></h1><p>${esc(t('heroBody'))}</p><div class="hero-actions">${button(resume?'resume':'intro',t(resume?'resume':'begin'),'arrow','',`data-unit="${u.id}"`)}<button class="textbtn" data-action="alpha">${icon('alpha',20)}${esc(t('alpha'))}</button></div></div>${art()}</section><div class="home-columns"><div><div class="section-title"><h2>${esc(t('journeyTitle'))}</h2><span class="sub">${esc(t('unitsCount'))}</span></div><div class="recommend"><div><div class="eyebrow">${esc(t('recommended'))}</div><h3>${esc(title(u.id))}</h3><p>${esc(t('unit',{n:u.index+1}))} · ${esc(modeName(nextMode(u.id)))}</p></div>${button('intro',t('continue'),'arrow','coral small',`data-unit="${u.id}"`)}</div>${courseList()}</div><aside class="aside"><div class="sidecard lilac">${icon('star',28)}<h3>${esc(t('completeUnit'))}</h3><div class="minirow"><strong>${completedCount()}<span style="font-size:13px;font-weight:500"> / ${COURSE.units.length*MODES.length}</span></strong><span>${esc(NAMES[store.settings.target])}</span></div><div class="minibar"><span style="width:${completedCount()/(COURSE.units.length*MODES.length)*100}%"></span></div><p>${esc(t('journeySub'))}</p></div><div class="sidecard">${icon('review',27)}<h3>${esc(t('due',{n:due.length}))}</h3><p>${esc(due.length?t('reviewDesc'):t('reviewSoon'))}</p><button class="textbtn" data-action="nav" data-view="review">${esc(t('review'))}${icon('arrow',16,'right-arrow')}</button></div><div class="sidecard peach">${icon('tile',28)}<h3>${esc(t('coreTag'))}</h3><p>${esc(t('coreBody'))}</p></div></aside></div>`;}
function playView(){return `<div class="page-head"><div class="eyebrow">${esc(t('coreTag'))}</div><h1>${esc(t('play'))}</h1><p>${esc(t('journeySub'))}</p></div><div class="settings-card"><div class="field"><label for="free-unit">${esc(t('chooseUnit'))}</label><select id="free-unit">${COURSE.units.map(u=>`<option value="${u.id}" ${selectedUnit===u.id?'selected':''}>${u.index+1}. ${esc(title(u.id))}</option>`).join('')}</select></div>${modeCards()}${button('freeStart',t('startTable'),'play','coral')}</div><div class="rulebox"><div class="rulehead">${icon('tile',20)}${esc(t('boardTitle'))}</div><p>${esc(t('boardRules'))}</p></div>`;}
function modeCards(){return `<div class="mode-grid">${MODES.map(m=>`<button class="mode-card ${selectedMode===m?'selected':''}" data-action="mode" data-mode="${m}" aria-pressed="${selectedMode===m}"><span class="modeicon">${icon(modeIcon(m),23)}</span><strong>${esc(modeName(m))}</strong><small>${esc(t(m+'Desc'))}</small></button>`).join('')}</div>`;}
function intro(unit,mode){if(!UNIT.has(unit))return;selectedUnit=unit;selectedMode=mode||nextMode(unit);view='intro';game=null;render();window.scrollTo({top:0,behavior:'instant'});}
function introView(){const u=UNIT.get(selectedUnit);return `<section class="intro-wrap"><button class="textbtn" data-action="nav" data-view="home">${icon('back',18,'right-arrow')}${esc(t('back'))}</button><div class="page-head" style="margin-top:18px"><div class="eyebrow">${esc(t('unit',{n:u.index+1}))} / ${esc(t('levelIntro'))}</div><h1>${esc(title(u.id))}</h1><p>${esc(t('oneFocus'))}</p></div><div class="rulebox"><div class="rulehead">${icon('hint',20)}${esc(t('oneThing'))}</div><p lang="${store.settings.support}" dir="${dir(store.settings.support)}">${esc(u.rules[store.settings.target][store.settings.support])}</p></div><div class="example-grid">${unitItems(u.id).map(item=>`<article class="example-card"><div class="targetline" lang="${store.settings.target}" dir="${dir(store.settings.target)}">${esc(item.text[store.settings.target])}</div><div class="supportline" lang="${store.settings.support}" dir="${dir(store.settings.support)}">${esc(item.text[store.settings.support])}</div>${sounds(store.settings.target,item.text[store.settings.target],item.id)}</article>`).join('')}</div><h3>${esc(t('practiceMode'))}</h3>${modeCards()}<div class="intro-actions"><span class="quiet">${icon('heart',19)}${esc(t('noHearts'))}</span>${button('start',t('startTable'),'play','coral')}</div><p class="tiny-note">${esc(t('boardRules'))}</p></section>`;}
function pairPool(unit){const current=unitItems(unit),u=UNIT.get(unit);const previous=COURSE.items.filter(i=>UNIT.get(i.unitId).index<u.index);const extra=previous.length?previous.slice(-3):COURSE.vocab.slice(0,3);return [...current,...extra];}
function startGame(){
 const s=store.settings;game={version:6,id:Date.now().toString(36)+Math.random().toString(36).slice(2,7),unit:selectedUnit,mode:selectedMode,route:route(),target:s.target,support:s.support,board:[],pairSelected:null,prefix:[],history:[],results:[],completed:[],score:0,combo:0,bestCombo:0,errors:0,tries:0,helpUses:{hint:0,shuffle:0},helpPending:null,assist:{},mistakes:{},heard:[],transcript:false,revealed:[],writePending:null,hints:[],round:0,phase:'playing',feedback:null};
 if(['pair','listen','write'].includes(game.mode)){game.pool=pairPool(game.unit).map(i=>i.id);game.board=makePairs(game.pool.map(i=>ITEM.get(i)),s.target,s.support);}else{game.pool=UNIT.get(game.unit).items;game.board=makeSequence(payloadsFor(unitItems(game.unit),s.target));}
 for(const id of game.pool){const k=game.route+'|'+id;if(!store.seen.includes(k))store.seen.push(k);}
 view='game';save();render();window.scrollTo({top:0,behavior:'instant'});
 if(game.mode==='listen'&&!player.available(game.target))toast(t('audioUnavailable'),true);
}
function resume(){const g=store.sessions[route()];if(!validSession(g)){delete store.sessions[route()];save();return intro(nextUnit().id);}game=sanitizeSession(g);selectedUnit=g.unit;selectedMode=g.mode;view='game';render();}
function progressFraction(){return ['pair','listen','write'].includes(game.mode)?game.completed.length/game.pool.length:game.completed.length/3;}
